const staticData = $getWorkflowStaticData('global');
const session = $node['Normalize + Validate Input'].json;
const runId = session.runId;
const run = staticData.runs?.[runId];

// SeedUrls from Wikidata Search Entities (hardcoded municipality data)
const allSeedUrls = $node['Wikidata Search Entities'].json.seedUrls || [];

// CRITICAL FIX: Separate PDFs from HTML pages.
// PDFs go directly to run._harvested → processed by OCR.Space in 2nd pass (ENABLED).
// HTML index pages go in 1st-pass queue → fetched → harvest more PDF links.
const isPdf = u => u.toLowerCase().endsWith('.pdf') || u.toLowerCase().endsWith('.csv') || u.toLowerCase().endsWith('.xlsx');
const pdfSeeds = allSeedUrls.filter(isPdf);
const htmlSeeds = allSeedUrls.filter(u => !isPdf(u));

// Pre-load PDF seeds into run._harvested so 2nd pass picks them up
if (run) {
  run._harvested = run._harvested || [];
  for (const u of pdfSeeds) {
    if (!run._harvested.includes(u)) run._harvested.push(u);
  }
  run.logs.push({ t: new Date().toISOString(), m: `Pre-seeded ${pdfSeeds.length} PDF URLs into 2nd-pass queue` });
}

// Extract additional URLs from DuckDuckGo if any
const ddgRaw = $input.first().json;
const found = [];
if (ddgRaw?.data || typeof ddgRaw === 'string') {
  const html = ddgRaw?.data || (typeof ddgRaw === 'string' ? ddgRaw : '');
  const re = /uddg=([^&"]+)/g;
  let m;
  while ((m = re.exec(html)) !== null) {
    try {
      const url = decodeURIComponent(m[1]);
      if (url.startsWith('http')) found.push(url);
    } catch(e) {}
  }
}

function scoreUrl(u) {
  let s = 0;
  const lu = u.toLowerCase();
  if (lu.includes('gob.ar')) s += 5;
  if (lu.includes('municip')) s += 2;
  if (lu.includes('transpar')) s += 3;
  if (lu.includes('licit') || lu.includes('compra') || lu.includes('contrat')) s += 3;
  if (lu.includes('presup') || lu.includes('auditor') || lu.includes('boletin') || lu.includes('ordenanza')) s += 2;
  if (lu.endsWith('.csv') || lu.endsWith('.xlsx') || lu.includes('/api/')) s += 3;
  if (lu.includes('ckan') || lu.includes('datastore') || lu.includes('dataset')) s += 4;
  return s;
}

// Separate DDG results: PDFs → harvested, HTML → first pass
const ddgPdfs = found.filter(isPdf);
const ddgHtml = found.filter(u => !isPdf(u));

if (run && ddgPdfs.length) {
  for (const u of ddgPdfs) {
    if (!run._harvested.includes(u)) run._harvested.push(u);
  }
}

// First-pass queue: only HTML/JSON pages (index pages that link to documents)
const allHtml = [...htmlSeeds, ...ddgHtml];
const uniq = [...new Set(allHtml)].filter(u => typeof u === 'string' && u.startsWith('http'));
uniq.sort((a, b) => scoreUrl(b) - scoreUrl(a));

const maxUrls = session.isPremium ? 40 : 15;
const queue = uniq.slice(0, maxUrls);

if (run) {
  run.step = 'discover_sources';
  run.progress = 18;
  run.logs.push({ t: new Date().toISOString(), m: `1st-pass queue: ${queue.length} HTML pages | 2nd-pass: ${(run._harvested||[]).length} PDFs queued for OCR` });
}

return queue.map(url => ({
  runId,
  localityName: session.localityName,
  dateFrom: session.dateFrom,
  dateTo: session.dateTo,
  isPremium: session.isPremium,
  url
}));
